    if mibBuilder.loadTexts: ciscoMetroPhyMIB.setRevisionsDescriptions(('Following objects have been added to cmPhyIfTable:\n        cmPhyIfRate,\n        cmPhyIfNegotiatedRate,\n        cmPhyIfOverSubscription,\n        cmPhyIfClientSubrate,\n        cmPhyIfClientSubrateLock.\n\n        Following Textual conventions have been added:\n        CmRateType,\n        CmNegotiatedRateType.\n        ', "cmPhyIfTransType object has been added to cmPhyIfTable.\n         'e1', 't1', 'e3', 't3', 'dvb', 'sdi' and 'its' enumeration \n         has been added to cmPhyIfProtocol object.", 'cmPhyIfAutoNegotiation object has been added to cmPhyIfTable.', 'cmPhyIfTxBufferSize object has been added to cmPhyIfTable.', 'The third revision of this MIB.\n \n        The following new counters have been added - \n        cmPhyRxCRC,\n        cmPhyRxCRCOverflow,\n        cmPhyHCRxCRC,\n        cmPhyTxEncapFarEndPktErrors,\n        cmPhyTxEncapFarEndPktErrOverflow,\n        cmPhyHCTxEncapFarEndPktErrors \n\n        The following objects have been deprecated -\n        cmPhyIfLaserSafetyControl (moved to CISCO-OPTICAL-IF-EXTN-MIB),\n        cmPhyIfForwardLaserControl (moved to CISCO-OPTICAL-IF-EXTN-MIB),\n        cmPhyRxPower (moved to CISCO-OPTICAL-MONITOR-MIB), \n        cmPhyRxHEC (moved to CISCO-CDL-MIB),\n        cmPhyRxHECOverflow (moved to CISCO-CDL-MIB) and\n        cmPhyHCRxHEC (moved to CISCO-CDL-MIB).\n        ', 'The second revision of this MIB.', 'The initial revision of this MIB.',))
