cmPhyIfOverSubscription = MibTableColumn((1, 3, 6, 1, 4, 1, 9, 10, 69, 1, 1, 1, 1, 14), TriValue().clone('false')).setMaxAccess("readwrite")
if mibBuilder.loadTexts: cmPhyIfOverSubscription.setStatus('current')
if mibBuilder.loadTexts: cmPhyIfOverSubscription.setDescription("Oversubscription allows the user to carry multiple clients\n        over the trunk to efficiently utilize the trunk bandwidth.\n\n        This object allows the management client to enable \n        over subscription on an interface by setting a value\n        of 'true' to this object. A 'false' value would disable\n        over subscription. Setting the value 'notApplicable' to\n        this object is not allowed. The value of 'notApplicable'\n        implies that this object does not apply to this interface.")
cmPhyIfClientSubrate = MibTableColumn((1, 3, 6, 1, 4, 1, 9, 10, 69, 1, 1, 1, 1, 15), Unsigned32().subtype(subtypeSpec=ValueRangeConstraint(0, 4240)).clone(0)).setUnits('mega-bytes-per-second').setMaxAccess("readwrite")
